.button {
  min-height: 44px;
  padding: 0.75rem 1rem;
  border: 1px solid transparent;
  border-radius: 0.875rem;
  font: inherit;
  font-weight: 650;
  cursor: pointer;
}

.primary {
  background: var(--color-accent);
  color: var(--color-on-accent);
}

.secondary {
  background: var(--color-surface);
  color: var(--color-ink);
}

.danger {
  background: var(--color-danger);
  color: var(--color-on-danger);
}

.button:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}

[data-focus-demo='1'] .search-panel .button {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}

.button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

[data-variant='before'] .button {
  min-height: 36px;
  padding: 0.4rem 0.6rem;
  border-radius: 0.25rem;
  font-weight: 500;
}

--- SearchPage.js ---
import { buttonMarkup } from './Button.js'

export function searchPageMarkup() {
  return `
    <section class="panel search-panel" aria-labelledby="search-title">
      <h2 id="search-title">Search</h2>
      <label class="field">
        <span>Query</span>
        <input name="query" type="search" autocomplete="off">
      </label>
      <div class="actions">
        ${buttonMarkup({ label: 'Search', tone: 'primary' })}
      </div>
    </section>
  `
}

--- SettingsPage.js ---
import { buttonMarkup } from './Button.js'

export function settingsPageMarkup({ saving = false } = {}) {
  return `
    <section class="panel settings-panel" aria-labelledby="settings-title">
      <h2 id="settings-title">Settings</h2>
      <p>Keep your account details and notification preferences current.</p>
      <div class="actions">
        ${buttonMarkup({ label: 'Cancel', tone: 'secondary' })}
        ${buttonMarkup({ label: 'Delete account', disabled: saving, tone: 'danger' })}
      </div>
    </section>
  `
}

