@import './button.module.css';

:root {
  color-scheme: light;
  font-family: 'Segoe UI', sans-serif;
  color: #17201c;
  background: #eef2ec;
  --color-accent: #1e6a4a;
  --color-on-accent: #ffffff;
  --color-surface: #ffffff;
  --color-ink: #17201c;
  --color-danger: #9f2d25;
