}

body {
  margin: 0;
  min-width: 320px;
}

#app {
  width: min(100% - 2rem, 980px);
  margin: 0 auto;
  padding: 2rem 0 3rem;
}

.page-header {
  max-width: 42rem;
}

.page-header p,
.panel p {
  overflow-wrap: anywhere;
}

.eyebrow {
  margin: 0 0 0.5rem;
  color: #53635b;
  font-size: 0.8rem;
  font-weight: 700;
