  margin-top: 2rem;
}

.panel {
  min-width: 0;
  padding: 1.25rem;
  border: 1px solid #d4ddd6;
  border-radius: 1rem;
  background: var(--color-surface);
  box-shadow: 0 12px 30px rgb(31 53 40 / 8%);
}

.field {
  display: grid;
  gap: 0.5rem;
  margin-top: 1.25rem;
  font-weight: 600;
}

.field input {
  width: 100%;
  min-width: 0;
  padding: 0.75rem 0.85rem;
  border: 1px solid #8d9d93;
  border-radius: 0.6rem;
  font: inherit;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

@media (max-width: 700px) {
