import assert from 'node:assert/strict'
import { test } from 'node:test'
import { classifyWorkerFailure, projectWorkerFailure } from './src/worker-client.js'

const workerFailure = {
  error: {
    kind: 'permission-denied',
    message: 'Account permission is required',
    detail: { action: 'delete-account', requiredRole: 'owner' },
  },
}

test('worker boundary preserves the project machine identity', () => {
  assert.equal(projectWorkerFailure(workerFailure).kind, 'permission-denied')
})

test('worker boundary preserves structured detail', () => {
  assert.deepEqual(projectWorkerFailure(workerFailure).detail, {
    action: 'delete-account',
    requiredRole: 'owner',
  })
})

test('consumer routes on kind, not message text', () => {
  assert.equal(
    classifyWorkerFailure({ kind: 'permission-denied', message: 'Try again' }),
    'request-access',
  )
  assert.equal(
    classifyWorkerFailure({ kind: 'transient', message: 'permission service unavailable' }),
    'retry',
  )
})
EOF"

